def subtract(a, b):
    # Merge overlapping/touching intervals in a list
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge them
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add as new interval
                merged.append([start, end])

        return merged

    # Merge both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    # For each interval in a, subtract all intervals in b
    result = []

    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_intervals = []

            for c_start, c_end in current_intervals:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    next_intervals.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if c_start < b_start:
                        next_intervals.append([c_start, b_start])
                    if b_end < c_end:
                        next_intervals.append([b_end, c_end])

            current_intervals = next_intervals

        result.extend(current_intervals)

    # Merge touching intervals in result
    return merge_intervals(result)

